upper_missing_weight_half_bound.statement:
lemma upper_missing_weight_half_bound {w b u v : ℝ}
    (hw : 0 ≤ w) (hb : b ≤ (1 / 2 : ℝ) * (u + v)) :
    2 * (w * b) ≤ w * u + w * v

